class WebScraper:
    def __init__(self):
        self.session = requests.Session()
        self.session.headers.update({
            'UserAgent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1'
        })

    def extract_price_and_discount(self, text):
        """Extract original price, sale price, and discount percentage from text"""
         Common Hungarian price patterns
        price_patterns = [
            r'(\d+\.?\d)\sFt',
            r'(\d+\.?\d)\sforint',
            r'(\d+\.?\d)\sHUF'
        ]

         Discount percentage patterns
        discount_patterns = [
            r'(\d+)%\skedvezmény',
            r'(\d+)%\soff',
            r'(\d+)%\sakció',
            r'(\d+)%',
            r'(\d+)\s%\smegtakarítás'
        ]

        prices = []
        for pattern in price_patterns:
            matches = re.findall(pattern, text, re.IGNORECASE)
            prices.extend([float(match.replace('.', '')) for match in matches])

        discounts = []
        for pattern in discount_patterns:
            matches = re.findall(pattern, text, re.IGNORECASE)
            discounts.extend([int(match) for match in matches])

         Calculate discount if we have old and new prices
        calculated_discount = 0
        if len(prices) >= 2:
            old_price = max(prices)
            new_price = min(prices)
            if old_price > new_price:
                calculated_discount = int(((old_price  new_price) / old_price)  100)

         Use explicit discount if available, otherwise calculated
        final_discount = max(discounts) if discounts else calculated_discount

        return {
            'original_price': max(prices) if prices else 0,
            'sale_price': min(prices) if prices else 0,
            'discount_percentage': final_discount
        }

    def scrape_website(self, website_key, website_config):
        """Scrape a single website for promotional offers"""
        logger.info(f"Starting scrape of {website_config['name']}")
        offers = []

        try:
            base_url = website_config['base_url']

             First, try to get sitemap or main pages
            main_urls = [base_url]
            for path in website_config['category_paths']:
                main_urls.append(urljoin(base_url, path))

            for url in main_urls:
                try:
                    logger.debug(f"Scraping URL: {url}")
                    response = self.session.get(url, timeout=15)
                    response.raise_for_status()

                    soup = BeautifulSoup(response.content, 'html.parser')

                     Extract all links from the page for deeper scraping
                    links = soup.find_all('a', href=True)
                    product_urls = []

                    for link in links:
                        if hasattr(link, 'get'):
                            href = link.get('href')
                        else:
                            continue
                        if not href:
                            continue
                        href = str(href)
                        if href.startswith('/'):
                            full_url = urljoin(base_url, href)
                        elif href.startswith('http'):
                            if website_key in href:
                                full_url = href
                            else:
                                continue
                        else:
                            continue

                         Look for product or promotion URLs
                        if any(keyword in href.lower() for keyword in ['termek', 'product', 'akcio', 'sale', 'offer', 'promo']):
                            product_urls.append(full_url)

                     Limit to avoid overwhelming the server
                    product_urls = list(set(product_urls))[:50]

                     Extract text content using trafilatura
                    downloaded = trafilatura.fetch_url(url)
                    if downloaded:
                        text_content = trafilatura.extract(downloaded)
                        if text_content:
                             Look for promotional keywords in the main page
                            promo_keywords = ['akció', 'kedvezmény', 'kiárusítás', 'sale', '%', 'ft', 'forint']
                            if any(keyword in text_content.lower() for keyword in promo_keywords):
                                price_info = self.extract_price_and_discount(text_content)
                                if price_info['discount_percentage'] > 0:
                                     Extract product title from page
                                    title_element = soup.find('title')
                                    title = title_element.text.strip() if title_element else 'Akciós termék'

                                    offers.append({
                                        'title': title,
                                        'url': url,
                                        'store': website_config['name'],
                                        'original_price': price_info['original_price'],
                                        'sale_price': price_info['sale_price'],
                                        'discount_percentage': price_info['discount_percentage'],
                                        'scraped_at': datetime.now().isoformat()
                                    })

                     Scrape product pages
                    for product_url in product_urls[:20]:   Limit to avoid timeouts
                        try:
                            time.sleep(0.5)   Rate limiting
                            product_response = self.session.get(product_url, timeout=10)
                            product_response.raise_for_status()

                            product_soup = BeautifulSoup(product_response.content, 'html.parser')

                             Use trafilatura for better content extraction
                            product_downloaded = trafilatura.fetch_url(product_url)
                            if product_downloaded:
                                product_text = trafilatura.extract(product_downloaded)
                                if product_text:
                                    price_info = self.extract_price_and_discount(product_text)
                                    if price_info['discount_percentage'] > 0:
                                         Extract product title
                                        title_element = product_soup.find('title')
                                        title = title_element.text.strip() if title_element else 'Akciós termék'

                                         Clean title
                                        title = re.sub(r'\s+', ' ', title).strip()
                                        if len(title) > 100:
                                            title = title[:97] + '...'

                                        offers.append({
                                            'title': title,
                                            'url': product_url,
                                            'store': website_config['name'],
                                            'original_price': price_info['original_price'],
                                            'sale_price': price_info['sale_price'],
                                            'discount_percentage': price_info['discount_percentage'],
                                            'scraped_at': datetime.now().isoformat()
                                        })

                        except Exception as e:
                            logger.warning(f"Error scraping product {product_url}: {e}")
                            continue

                except Exception as e:
                    logger.warning(f"Error scraping {url}: {e}")
                    continue

        except Exception as e:
            logger.error(f"Error scraping {website_config['name']}: {e}")

        logger.info(f"Found {len(offers)} offers from {website_config['name']}")
        return offers

def scrape_all_websites():
    """Scrape all configured websites concurrently"""
    logger.info("Starting comprehensive website scraping...")

    scraper = WebScraper()
    all_offers = []

     Use threading for concurrent scraping
    def scrape_single(website_key, website_config, results):
        try:
            offers = scraper.scrape_website(website_key, website_config)
            results.extend(offers)
        except Exception as e:
            logger.error(f"Error in thread for {website_key}: {e}")

    threads = []
    results = []

    for website_key, website_config in WEBSITES.items():
        thread = threading.Thread(
            target=scrape_single,
            args=(website_key, website_config, results)
        )
        threads.append(thread)
        thread.start()

     Wait for all threads to complete
    for thread in threads:
        thread.join(timeout=120)   2 minute timeout per thread

     Remove duplicates and sort by discount percentage
    seen_urls = set()
    unique_offers = []

    for offer in results:
        if offer['url'] not in seen_urls and offer['discount_percentage'] > 0:
            seen_urls.add(offer['url'])
            unique_offers.append(offer)

     Sort by discount percentage (highest first)
    unique_offers.sort(key=lambda x: x['discount_percentage'], reverse=True)

     Update global data
    with data_lock:
        offers_data['offers'] = unique_offers
        offers_data['last_updated'] = datetime.now().isoformat()
        offers_data['status'] = 'updated'

    logger.info(f"Scraping completed. Found {len(unique_offers)} unique offers.")

def periodic_scraper():
    """Run scraping periodically"""
    while True:
        try:
            scrape_all_websites()
             Wait 30 minutes before next scrape
            time.sleep(1800)
        except Exception as e:
            logger.error(f"Error in periodic scraper: {e}")
            time.sleep(300)   Wait 5 minutes on error

 Routes
@app.route('/')
def index():
    return render_template('index.html')

@app.route('/api/offers')
def get_offers():
    with data_lock:
        return jsonify(offers_data)

@app.route('/api/refresh')
def refresh_offers():
    """Trigger immediate refresh"""
    threading.Thread(target=scrape_all_websites, daemon=True).start()
    return jsonify({'status': 'refresh_started'})

@app.route('/manifest.json')
def manifest():
    return app.send_static_file('manifest.json')

@app.route('/sw.js')
def service_worker():
    return app.send_static_file('sw.js')

 Start background scraping thread
scraper_thread = threading.Thread(target=periodic_scraper, daemon=True)
scraper_thread.start()

 Initial scrape
initial_scrape_thread = threading.Thread(target=scrape_all_websites, daemon=True)
initial_scrape_thread.start()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=True)

