# Promóciós kulcsszavak
PROMO_KEYWORDS = ["akció", "kedvezmény", "kiárusítás", "sale", "%", "ft", "forint", "megtakarítás", "kupon", "outlet"]

class WebScraper:
    def __init__(self, respect_robots=True):
        self.session = requests.Session()
        self.session.headers.update({
            "User-Agent": (
                "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) "
                "AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1"
            )
        })
        self.timeout = (10, 20)  # connect, read
        self.respect_robots = respect_robots
        self.robots_cache = {}

    def can_fetch(self, base_url, path="/"):
        if not self.respect_robots:
            return True
        try:
            parsed = urlparse(base_url)
            robots_url = f"{parsed.scheme}://{parsed.netloc}/robots.txt"
            if robots_url not in self.robots_cache:
                rp = robotparser.RobotFileParser()
                rp.set_url(robots_url)
                try:
                    rp.read()
                except Exception:
                    # Ha hibás vagy nincs robots.txt, óvatosan továbbmegy
                    self.robots_cache[robots_url] = None
                    return True
                self.robots_cache[robots_url] = rp
            rp = self.robots_cache.get(robots_url)
            if rp is None:
                return True
            return rp.can_fetch(self.session.headers.get("User-Agent", "*"), path)
        except Exception:
            return True

    def rate_limit_sleep(self):
        # enyhe jitter, hogy ne legyünk mintázatszerűek
        time.sleep(0.6 + random.random() * 0.6)

    def extract_price_and_discount(self, text):
        price_patterns = [
            r'(\d{1,3}(?:\.\d{3})+|\d+)\s*Ft',
            r'(\d{1,3}(?:\.\d{3})+|\d+)\s*forint',
            r'(\d{1,3}(?:\.\d{3})+|\d+)\s*HUF'
        ]
        discount_patterns = [
            r'(\d+)\s*%\s*kedvezm[eé]ny',
            r'(\d+)\s*%\s*off',
            r'(\d+)\s*%\s*akci[oó]',
            r'-(\d+)\s*%',
            r'(\d+)\s*%\s*megtakar[ií]t[aá]s'
        ]

        prices = []
        for pattern in price_patterns:
            for match in re.findall(pattern, text, flags=re.IGNORECASE):
                try:
                    prices.append(float(str(match).replace(".", "")))
                except Exception:
                    pass

        discounts = []
        for pattern in discount_patterns:
            for match in re.findall(pattern, text, flags=re.IGNORECASE):
                try:
                    discounts.append(int(match))
                except Exception:
                    pass

        calculated_discount = 0
        if len(prices) >= 2:
            old_price = max(prices)
            new_price = min(prices)
            if old_price > new_price > 0:
                calculated_discount = int(((old_price - new_price) / old_price) * 100)

        final_discount = max(discounts) if discounts else calculated_discount

        return {
            "original_price": int(max(prices)) if prices else 0,
            "sale_price": int(min(prices)) if prices else 0,
            "discount_percentage": int(final_discount) if final_discount else 0
        }

    def get_text(self, url):
        try:
            downloaded = trafilatura.fetch_url(url)
            if not downloaded:
                return ""
            extracted = trafilatura.extract(downloaded, include_tables=False, include_images=False)
            return extracted or ""
        except Exception:
            return ""

    def fetch_soup(self, url):
        self.rate_limit_sleep()
        resp = self.session.get(url, timeout=self.timeout)
        resp.raise_for_status()
        return BeautifulSoup(resp.content, "html.parser")

    def is_same_site(self, website_key, href):
        try:
            netloc = urlparse(href).netloc
            return website_key in netloc
        except Exception:
            return False

    def build_main_urls(self, website_config):
        base_url = website_config["base_url"]
        urls = [base_url]
        for path in website_config.get("category_paths", []):
            if not path.startswith("/"):
                path = "/" + path
            urls.append(urljoin(base_url, path))
        # egyedi: hozzáadjuk /akcio vagy /sale, ha nincs a listában
        for extra in ["/akcio", "/sale"]:
            full = urljoin(base_url, extra)
            if full not in urls:
                urls.append(full)
        return list(dict.fromkeys(urls))

    def scrape_website(self, website_key, website_config):
        logger.info(f"Kezdődik a lekérés: {website_config['name']}")
        offers = []
        base_url = website_config["base_url"]

        try:
            main_urls = self.build_main_urls(website_config)

            for url in main_urls:
                path_ok = self.can_fetch(base_url, urlparse(url).path or "/")
                if not path_ok:
                    logger.info(f"robots.txt tiltja: {url}")
                    continue

                try:
                    soup = self.fetch_soup(url)
                except Exception as e:
                    logger.warning(f"Hiba a főoldal letöltésénél: {url} - {e}")
                    continue

                # főoldal szövegtartalom és promó kulcsszavak
                page_text = self.get_text(url)
                if page_text and any(k in page_text.lower() for k in PROMO_KEYWORDS):
                    price_info = self.extract_price_and_discount(page_text)
                    if price_info["discount_percentage"] > 0:
                        title_el = soup.find("title")
                        title = title_el.get_text(strip=True) if title_el else "Akciók"
                        offers.append({
                            "title": title[:100],
                            "url": url,
                            "store": website_config["name"],
                            "original_price": price_info["original_price"],
                            "sale_price": price_info["sale_price"],
                            "discount_percentage": price_info["discount_percentage"],
                            "scraped_at": datetime.now().isoformat()
                        })

                # Termék/promo linkek kigyűjtése
                links = soup.find_all("a", href=True)
                product_urls = []
                for a in links:
                    href = str(a.get("href", "")).strip()
                    if not href:
                        continue
                    if href.startswith("/"):
                        full_url = urljoin(base_url, href)
                    elif href.startswith("http"):
                        if self.is_same_site(website_key, href):
                            full_url = href
                        else:
                            continue
                    else:
                        continue

                    h = href.lower()
                    if any(kw in h for kw in ["termek", "product", "akcio", "sale", "offer", "promo", "deal"]):
                        product_urls.append(full_url)

                # limitáljuk és egyedivé tesszük
                product_urls = list(dict.fromkeys(product_urls))[:40]

                # Termékoldalak elemzése
                for purl in product_urls:
                    if not self.can_fetch(base_url, urlparse(purl).path or "/"):
                        continue
                    try:
                        product_soup = self.fetch_soup(purl)
                        product_text = self.get_text(purl)
                        if not product_text:
                            continue
                        price_info = self.extract_price_and_discount(product_text)
                        if price_info["discount_percentage"] <= 0:
                            continue

                        title_el = product_soup.find("title")
                        title = title_el.get_text(strip=True) if title_el else "Akciós termék"
                        title = re.sub(r"\s+", " ", title).strip()
                        if len(title) > 100:
                            title = title[:97] + "..."

                        offers.append({
                            "title": title,
                            "url": purl,
                            "store": website_config["name"],
                            "original_price": price_info["original_price"],
                            "sale_price": price_info["sale_price"],
                            "discount_percentage": price_info["discount_percentage"],
                            "scraped_at": datetime.now().isoformat()
                        })

                    except requests.HTTPError as he:
                        code = getattr(he.response, "status_code", None)
                        if code in (403, 429):
                            logger.warning(f"Hozzáférés korlátozva ({code}): {purl}")
                            # ha sok a 429/403, később érdemes proxy/backoff
                        else:
                            logger.warning(f"HTTP hiba: {purl} - {he}")
                    except Exception as e:
                        logger.warning(f"Hiba a termékoldalnál: {purl} - {e}")
                        continue

        except Exception as e:
            logger.error(f"Hiba a(z) {website_config['name']} lekérése közben: {e}")

        logger.info(f"Talált ajánlatok: {len(offers)} - {website_config['name']}")
        return offers


def scrape_all_websites():
    logger.info("Teljes lekérés indul...")
    scraper = WebScraper(respect_robots=True)
    results = []

    def worker(site_key, site_cfg, sink):
        try:
            data = scraper.scrape_website(site_key, site_cfg)
            sink.extend(data)
        except Exception as e:
